  /* 밝은 면 색(명도 74% 이상)은 채도를 0.35 이하로 → 넓은 배경 면이 눈부시지 않게(규격: 배경 채도 35% 이하).
     불빛처럼 일부러 밝게 둔 작은 점 색(LIGHTS)만 그대로 둔다. 장면마다 한 번만 계산해 둔다 */
  const LIGHTS = ['#FFE9A8', '#FFE08A', '#FFD25A', '#FFE27A', '#F6E7A0', '#FFF3B0'];
  const lightOf = hex => { const n = parseInt(hex.slice(1), 16), r = (n >> 16 & 255) / 255, g = (n >> 8 & 255) / 255, b = (n & 255) / 255; return (Math.max(r, g, b) + Math.min(r, g, b)) / 2; };
  const calmAll = s => s.replace(/(fill|stop-color)="(#[0-9A-Fa-f]{6})"/g, (m, a, c) => LIGHTS.includes(c.toUpperCase()) || lightOf(c) < .74 ? m : `${a}="${calm(c, .35)}"`);
  /* 장면 그림은 판마다 같으니 한 번 그려 두고(id 자리 'UQZ'), 판마다 고유 id(u)만 바꿔 끼운다 */
  const CACHE = {};
  const svgOf = (sc, u) => {
    if(!CACHE[sc.key]){ FACES = []; CACHE[sc.key] = calmAll(wrap(sc.draw('UQZ'))); sc.faces = FACES; }
    return CACHE[sc.key].replace(/UQZ/g, u);
  };
  return { W, H, K, ZX, ZY, SC, SPOTS, svgOf };
